css:
@font-face{font-family:KumoProductInter;src:url("https://gauravtiwari.org/wp-content/uploads/kumo-hybrid-product/InterVariable.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap}
.khp{--khp-canvas:light-dark(#fafafa,#101010);--khp-base:light-dark(#fff,#1b1b1b);--khp-recessed:light-dark(#f5f5f5,#262626);--khp-text:light-dark(#171717,#f5f5f5);--khp-subtle:light-dark(#626262,#b0b0b0);--khp-line:light-dark(#e7e7e7,#363636);--khp-control:light-dark(#cdcdcd,#525252);--khp-brand:#2563eb;--khp-link:light-dark(#183fa0,#9bb8ff);color-scheme:light;background:var(--khp-canvas);color:var(--khp-text);font-family:KumoProductInter,InterVariable,system-ui,sans-serif;font-size:18px;line-height:1.75;font-feature-settings:"cv02","cv03","cv04","cv11","ss01";-webkit-font-smoothing:antialiased;isolation:isolate}
:root[data-theme="dark"] .khp{color-scheme:dark}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]) .khp{color-scheme:dark}}
.khp *,.khp *::before,.khp *::after{box-sizing:border-box}
.khp :where(h1,h2,h3,p,ul,ol,dl,dd,figure){margin:0}
.khp :where(h1,h2,h3){font-family:inherit;font-weight:600;color:var(--khp-text);letter-spacing:0;text-wrap:balance}
.khp h1{font-size:clamp(2.75rem,5vw,4rem);line-height:1.15;max-width:20ch}
.khp h2{font-size:clamp(1.75rem,3vw,2.25rem);line-height:1.25;max-width:30ch}
.khp h3{font-size:1.125rem;line-height:1.5}
.khp p{text-wrap:pretty}
.khp a{color:var(--khp-link);text-underline-offset:.2em}
.khp a:hover{text-decoration-thickness:2px}
.khp :where(a,summary,button):focus-visible{outline:2px solid var(--khp-text);outline-offset:4px}
.khp-wrap{width:min(1200px,calc(100% - 3rem));margin-inline:auto}
.khp-section{padding-block:clamp(2.5rem,6vw,4.5rem)}
.khp-section+.khp-section{border-top:1px solid var(--khp-line)}
.khp-split{display:grid;grid-template-columns:minmax(0,3fr) minmax(280px,2fr);gap:clamp(2rem,5vw,4rem);align-items:start}
.khp-hero{padding-block:clamp(3rem,7vw,5.5rem)}
.khp-badge{display:inline-flex;align-items:center;background:var(--khp-recessed);border:1px solid var(--khp-line);border-radius:5px;padding:.15rem .55rem;font-size:.8125rem;font-weight:500;line-height:1.5;margin-block-end:1.25rem}
.khp-lede{font-size:1.125rem;color:var(--khp-subtle);max-width:48ch;margin-block-start:1.25rem!important}
.khp-actions{display:flex;align-items:center;flex-wrap:wrap;gap:.75rem;margin-block-start:1.75rem}
.khp .khp-button{min-height:44px;display:inline-flex;align-items:center;justify-content:center;padding:.65rem 1rem;border:1px solid var(--khp-control);border-radius:7px;background:var(--khp-base);color:var(--khp-text);font-size:.875rem;font-weight:500;line-height:1.5;text-decoration:none}
.khp .khp-button:hover{background:var(--khp-recessed)}
.khp .khp-button-primary{background:var(--khp-brand);border-color:var(--khp-brand);color:#fff}
.khp .khp-button-primary:hover{background:#1d4ed8;border-color:#1d4ed8}
.khp-note{font-size:.875rem;color:var(--khp-subtle);margin-block-start:1rem!important;max-width:56ch}
.khp-layer{border:1px solid var(--khp-line);border-radius:12px;background:var(--khp-base);overflow:hidden}
.khp-layer-head{padding:.85rem 1.5rem;background:var(--khp-recessed);border-bottom:1px solid var(--khp-line);font-size:.875rem;font-weight:500}
.khp-layer-body{padding:1.5rem}
.khp-price{font-size:2rem;font-weight:600;line-height:1.25;color:var(--khp-text)}
.khp-layer-body>p+p{color:var(--khp-subtle);font-size:.875rem;margin-block-start:.5rem}
.khp-specs{margin-block-start:1.5rem!important;font-size:.875rem;font-variant-numeric:tabular-nums}
.khp-specs>div{display:flex;justify-content:space-between;gap:1.5rem;padding-block:.6rem;border-top:1px solid var(--khp-line)}
.khp-specs dt{color:var(--khp-subtle);font-weight:400}
.khp-specs dd{color:var(--khp-text);text-align:end;font-weight:500}
.khp-heading p{margin-block-start:.85rem;max-width:56ch;color:var(--khp-subtle)}
.khp-preview{padding-top:0}
.khp-stage{margin-block-start:2rem!important}
.khp-stage img{width:100%;height:auto;display:block}
.khp-stage figcaption{font-size:.875rem;color:var(--khp-subtle);padding:.9rem 1.5rem;border-top:1px solid var(--khp-line)}
.khp .khp-shot-dark{display:none}
:root[data-theme="dark"] .khp .khp-shot-light{display:none}
:root[data-theme="dark"] .khp .khp-shot-dark{display:block}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]) .khp .khp-shot-light{display:none}:root:not([data-theme="light"]) .khp .khp-shot-dark{display:block}}
.khp-feature-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:2.5rem 3rem;margin-block-start:2rem!important}
.khp-feature-grid>div{min-width:0;border-top:1px solid var(--khp-line);padding-top:1.25rem}
.khp-feature-grid dt{font-size:1.125rem;font-weight:600;color:var(--khp-text)}
.khp-feature-grid dd{font-size:1rem;color:var(--khp-subtle);margin-block-start:.65rem;max-width:56ch}
.khp-tour{list-style:none;padding:0;margin-block-start:2rem!important;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 3rem}
.khp-tour li{border-top:1px solid var(--khp-line);padding-block:1rem}
.khp-tour a{display:block;font-weight:500;text-decoration:none}
.khp-tour a:hover{text-decoration:underline}
.khp-tour p{font-size:1rem;color:var(--khp-subtle);margin-block-start:.35rem}
.khp-steps{padding-inline-start:1.4rem;margin-block-start:1.5rem!important;max-width:65ch}
.khp-steps li{padding-inline-start:.4rem;font-size:1rem}
.khp-steps li+li{margin-block-start:.85rem}
.khp-faq details{padding:1rem 1.25rem;border:1px solid var(--khp-line);border-radius:9px;background:var(--khp-base)}
.khp-faq details+details{margin-block-start:.75rem}
.khp-faq summary{cursor:pointer;font-size:1rem;font-weight:500;line-height:1.5}
.khp-faq details p{margin-block-start:.85rem;font-size:1rem;color:var(--khp-subtle)}
.khp-close{padding-bottom:3rem}
.khp-close-inner{padding:clamp(1.5rem,4vw,2.5rem);display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:2rem}
.khp-close-inner p{color:var(--khp-subtle);font-size:1rem;margin-block-start:.65rem}
.khp-attribution{font-size:.8125rem;color:var(--khp-subtle);padding-block:1.5rem;border-top:1px solid var(--khp-line)}
@media(max-width:800px){.khp-split{grid-template-columns:1fr}.khp-feature-grid,.khp-tour{grid-template-columns:1fr}.khp-faq{margin-block-start:.5rem}.khp-wrap{width:calc(100% - 2rem)}}
@media(pointer:coarse){.khp .khp-button{min-height:48px}.khp-tour a{min-height:44px;display:flex;align-items:center}}
@media(prefers-reduced-motion:reduce){.khp *{scroll-behavior:auto}}
